  $svg.Add($svgPath)
 }
 $vector = '<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="' + $item.w + 'dp" android:height="' + $item.h + 'dp" android:viewportWidth="' + $item.w + '" android:viewportHeight="' + $item.h + '">' + "`n" + ($paths -join "`n") + "`n</vector>`n"
 [IO.File]::WriteAllText((Join-Path $root ('app/src/main/res/drawable/' + $item.name + '.xml')), $vector, $utf8)
 $card = '<figure><svg viewBox="0 0 ' + $item.w + ' ' + $item.h + '">' + ($svg -join '') + '</svg><figcaption>' + $item.label + '</figcaption></figure>'
 if ($item.w -eq 96) { $caseCards.Add($card) } else { $sceneCards.Add($card) }
}
$html = '<!doctype html><html lang="en"><meta charset="utf-8"><title>Space Salvage - cases and backgrounds</title><style>body{background:#101b2f;color:#d0e2ea;font:15px system-ui;margin:24px}main{display:grid;grid-template-columns:repeat(8,1fr);gap:10px}figure{margin:0;background:#17283d;border-radius:14px;text-align:center;padding:10px}svg{width:90px;height:90px}figcaption{color:#9bbdc8;font-size:12px}.scenes{grid-template-columns:repeat(6,1fr)}.scenes svg{width:100%;height:310px}</style><h1>Space Salvage</h1><p>Flat cases / eight opening frames / matching quiet backgrounds</p><main>' + ($caseCards -join '') + '</main><h2>Scenes</h2><main class="scenes">' + ($sceneCards -join '') + '</main></html>'
[IO.File]::WriteAllText((Join-Path $root 'docs/minimal-cases-scenes-preview.html'), $html, $utf8)
Write-Output ('Created ' + $items.Count + ' flat vector assets.')

